42	func newActivityCmd() *cobra.Command {
43		cmd := &cobra.Command{
44			Use:   "activity",
45			Short: "Show your activity overview",
46			Long:  "Display your activity overview, repository breakdown, and recent commits from entire.io",
47			RunE: func(cmd *cobra.Command, _ []string) error {
48				return runActivity(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr())
49			},
50		}
51		return cmd
