54	func runActivity(ctx context.Context, w, errW io.Writer) error {
55		client, err := NewAuthenticatedAPIClient(false)
56		if err != nil {
57			fmt.Fprintln(errW, "Not logged in. Run 'entire login' to authenticate.")
58			return NewSilentError(err)
59		}
60	
61		// Non-interactive fallback: piped output or accessibility mode
62		if !isTerminalWriter(w) || IsAccessibleMode() {
63			return runActivityStatic(ctx, w, client)
64		}
65	
66		return runActivityTUI(ctx, client)
67	}
