69	func runActivityStatic(ctx context.Context, w io.Writer, client *api.Client) error {
70		var checkpoints []userCheckpoint
71		var streakDates []string
72		var commits []userCommit
73	
74		g, gCtx := errgroup.WithContext(ctx)
75		g.Go(func() error {
76			var fetchErr error
77			checkpoints, streakDates, fetchErr = fetchCheckpoints(gCtx, client)
78			return fetchErr
79		})
80		g.Go(func() error {
81			var fetchErr error
82			commits, fetchErr = fetchCommits(gCtx, client)
83			return fetchErr
84		})
85		if err := g.Wait(); err != nil {
86			return fmt.Errorf("fetch activity: %w", err)
87		}
88	
89		stats := computeContributionStats(checkpoints, streakDates)
90		repos := computeRepoContributions(checkpoints)
91		hourly := computeHourlyData(checkpoints)
92		days := groupCommitsByDay(commits)
93	
94		sty := newActivityStyles(w)
95		renderActivity(w, sty, stats, repos, hourly, days)
96		return nil
97	}
