99	func fetchCheckpoints(ctx context.Context, client *api.Client) ([]userCheckpoint, []string, error) {
100		path := fmt.Sprintf("/api/v1/stats/checkpoints?timeframe=%s&limit=%d", activityTimeframe, activityLimit)
101		resp, err := client.Get(ctx, path)
102		if err != nil {
103			return nil, nil, fmt.Errorf("GET checkpoints: %w", err)
104		}
105		defer resp.Body.Close()
106	
107		if err := api.CheckResponse(resp); err != nil {
108			return nil, nil, fmt.Errorf("checkpoints response: %w", err)
109		}
110	
111		var result userCheckpointsResponse
112		if err := api.DecodeJSON(resp, &result); err != nil {
113			return nil, nil, fmt.Errorf("decode checkpoints: %w", err)
114		}
115		return result.Checkpoints, result.StreakDates, nil
116	}
