137	// computeContributionStats mirrors the frontend's computeStats + computeStreaks.
138	func computeContributionStats(checkpoints []userCheckpoint, streakDates []string) contributionStats {
139		stats := contributionStats{}
140		if len(checkpoints) == 0 {
141			return stats
142		}
143	
144		stats.Tasks = len(checkpoints)
145	
146		var tokenSum, tokenCount, sessionSum, maxSteps int
147		for _, cp := range checkpoints {
148			if cp.InputTokens != nil || cp.OutputTokens != nil {
149				tokenSum += derefOr(cp.InputTokens, 0) + derefOr(cp.OutputTokens, 0)
150				tokenCount++
151			}
152			sessionSum += derefOr(cp.SessionCount, 1)
153			if s := derefOr(cp.Steps, 1); s > maxSteps {
154				maxSteps = s
155			}
156		}
157	
158		if tokenCount > 0 {
159			stats.Throughput = float64(tokenSum) / float64(tokenCount) / 1000.0
160		}
161		stats.Iteration = float64(sessionSum) / float64(len(checkpoints))
162		// 2 min/step is the frontend's heuristic for turn duration
163		stats.ContinuityH = float64(maxSteps) * 2.0 / 60.0
164		stats.Streak, stats.CurrentStreak = computeStreaks(streakDates)
165	
166		return stats
167	}
