169	func computeStreaks(timestamps []string) (longest, current int) {
170		if len(timestamps) == 0 {
171			return 0, 0
172		}
173	
174		dateSet := make(map[string]struct{})
175		for _, ts := range timestamps {
176			t, err := parseFlexibleTime(ts)
177			if err != nil {
178				continue
179			}
180			dateSet[t.Local().Format("2006-01-02")] = struct{}{}
181		}
182	
183		if len(dateSet) == 0 {
184			return 0, 0
185		}
186	
187		// Current streak: from today or yesterday backward
188		today := time.Now().Local().Format("2006-01-02")
189		check := time.Now().Local()
190		if _, ok := dateSet[today]; !ok {
191			check = check.AddDate(0, 0, -1)
192		}
193		for {
194			if _, ok := dateSet[check.Format("2006-01-02")]; !ok {
195				break
196			}
197			current++
198			check = check.AddDate(0, 0, -1)
199		}
200	
201		dates := make([]string, 0, len(dateSet))
202		for d := range dateSet {
203			dates = append(dates, d)
204		}
205		sort.Strings(dates)
206	
207		run := 1
208		longest = 1
209		for i := 1; i < len(dates); i++ {
210			prev, errP := time.Parse("2006-01-02", dates[i-1])
211			curr, errC := time.Parse("2006-01-02", dates[i])
212			if errP != nil || errC != nil {
213				run = 1
214				continue
215			}
216			if curr.Sub(prev).Hours() <= 25 { // 1 day with some tolerance
217				run++
218			} else {
219				run = 1
220			}
221			if run > longest {
222				longest = run
223			}
224		}
225	
226		return longest, current
227	}
