229	func computeRepoContributions(checkpoints []userCheckpoint) []repoContribution {
230		byRepo := make(map[string]*repoContribution)
231	
232		for _, cp := range checkpoints {
233			rc, ok := byRepo[cp.RepoFullName]
234			if !ok {
235				rc = &repoContribution{
236					Repo:   cp.RepoFullName,
237					Agents: make(map[string]int),
238				}
239				byRepo[cp.RepoFullName] = rc
240			}
241			rc.Total++
242			rc.Agents[normalizeAgentID(cp.Agent)]++
243		}
244	
245		result := make([]repoContribution, 0, len(byRepo))
246		for _, rc := range byRepo {
247			result = append(result, *rc)
248		}
249		sort.Slice(result, func(i, j int) bool {
250			if result[i].Total != result[j].Total {
251				return result[i].Total > result[j].Total
252			}
253			return result[i].Repo < result[j].Repo
254		})
255		return result
256	}
