258	// computeHourlyData groups checkpoints by date+hour+agent, summing steps.
259	func computeHourlyData(checkpoints []userCheckpoint) []hourlyPoint {
260		type key struct {
261			date    string
262			hour    int
263			agentID string
264		}
265		grouped := make(map[key]int)
266	
267		for _, cp := range checkpoints {
268			t, err := parseFlexibleTime(cp.CommitDate)
269			if err != nil {
270				continue
271			}
272			local := t.Local()
273			k := key{
274				date:    local.Format("2006-01-02"),
275				hour:    local.Hour(),
276				agentID: normalizeAgentID(cp.Agent),
277			}
278			grouped[k] += derefOr(cp.Steps, 1)
279		}
280	
281		result := make([]hourlyPoint, 0, len(grouped))
282		for k, v := range grouped {
283			result = append(result, hourlyPoint{
284				Date:    k.date,
285				Hour:    k.hour,
286				Value:   v,
287				AgentID: k.agentID,
288			})
289		}
290		return result
291	}
