293	func groupCommitsByDay(commits []userCommit) []commitDay {
294		byDate := make(map[string][]userCommit)
295		var dateOrder []string
296	
297		for _, c := range commits {
298			date := dateUnknown
299			if c.CommitDate != nil {
300				if t, err := parseFlexibleTime(*c.CommitDate); err == nil {
301					date = t.Local().Format("2006-01-02")
302				}
303			}
304			if _, exists := byDate[date]; !exists {
305				dateOrder = append(dateOrder, date)
306			}
307			byDate[date] = append(byDate[date], c)
308		}
309	
310		// Sort dates newest first, with unknown dates pushed to the end
311		sort.Slice(dateOrder, func(i, j int) bool {
312			if dateOrder[i] == dateUnknown {
313				return false
314			}
315			if dateOrder[j] == dateUnknown {
316				return true
317			}
318			return dateOrder[i] > dateOrder[j]
319		})
320	
321		result := make([]commitDay, 0, len(dateOrder))
322		for _, d := range dateOrder {
323			result = append(result, commitDay{Date: d, Commits: byDate[d]})
324		}
325		return result
326	}
