328	func normalizeAgentID(agent *string) string {
329		if agent == nil {
330			return agentUnknown
331		}
332		return normalizeAgentString(*agent)
333	}
334	
335	func normalizeAgentString(s string) string {
336		if s == "" {
337			return agentUnknown
338		}
339	
340		var sb strings.Builder
341		for _, r := range s {
342			if r == ' ' || r == '-' || r == '_' {
343				continue
344			}
345			if r >= 'A' && r <= 'Z' {
346				sb.WriteByte(byte(r + 32))
347			} else {
348				sb.WriteRune(r)
349			}
350		}
351		lower := sb.String()
352	
353		if id, ok := knownAgents[lower]; ok {
354			return id
355		}
356	
357		for _, suffix := range []string{"code", "cli"} {
358			if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
359				if id, ok := knownAgents[lower[:len(lower)-len(suffix)]]; ok {
360					return id
361				}
362			}
363		}
364	
365		if strings.HasPrefix(lower, "factoryaidroid") {
366			return "droid"
367		}
368	
369		return agentUnknown
370	}
371	
372	// parseFlexibleTime tries RFC3339, then RFC3339Nano.
373	func parseFlexibleTime(s string) (time.Time, error) {
374		t, err := time.Parse(time.RFC3339, s)
375		if err != nil {
376			t, err = time.Parse(time.RFC3339Nano, s)
377			if err != nil {
378				return time.Time{}, fmt.Errorf("parse time %q: %w", s, err)
379			}
380		}
381		return t, nil
382	}
383	
384	func derefOr(p *int, def int) int {
385		if p == nil {
386			return def
387		}
388		return *p
389	}
