134	func renderStatCards(w io.Writer, sty activityStyles, stats contributionStats) {
135		cards := []struct {
136			label string
137			value string
138			unit  string
139			desc  string
140		}{
141			{"THROUGHPUT", fmt.Sprintf("%.1f", stats.Throughput), "k", "Avg. tokens/checkpoint"},
142			{"ITERATION", fmt.Sprintf("%.1f", stats.Iteration), "x", "Avg sessions/checkpoint"},
143			{"CONTINUITY", fmt.Sprintf("%.1f", stats.ContinuityH), "h", "Peak session length"},
144			{"STREAK", strconv.Itoa(stats.Streak), " day", fmt.Sprintf("%d current", stats.CurrentStreak)},
145		}
146	
147		cardWidth := (sty.width - 3) / 4 // 3 separators
148		if cardWidth < 16 {
149			cardWidth = 16
150		}
151	
152		var topParts, midParts, botParts []string
153		for _, c := range cards {
154			lbl := padOrTruncate(c.label, cardWidth)
155			dsc := padOrTruncate(c.desc, cardWidth)
156	
157			topParts = append(topParts, sty.render(sty.label, lbl))
158			midParts = append(midParts, sty.render(sty.value, c.value)+sty.render(sty.unit, c.unit)+
159				strings.Repeat(" ", max(0, cardWidth-len(c.value)-len(c.unit))))
160			botParts = append(botParts, sty.render(sty.desc, dsc))
161		}
162	
163		sep := sty.render(sty.dim, " │ ")
164		fmt.Fprintln(w, strings.Join(topParts, sep))
165		fmt.Fprintln(w, strings.Join(midParts, sep))
166		fmt.Fprintln(w, strings.Join(botParts, sep))
167	}
