587	func renderCommitListN(w io.Writer, sty activityStyles, days []commitDay, maxDays int) {
588		if len(days) == 0 {
589			return
590		}
591	
592		if maxDays <= 0 || maxDays > len(days) {
593			maxDays = len(days)
594		}
595	
596		for _, day := range days[:maxDays] {
597			displayDate := formatCommitDate(day.Date)
598			commitWord := "commits"
599			if len(day.Commits) == 1 {
600				commitWord = "commit"
601			}
602	
603			fmt.Fprintf(w, "%s  %s\n",
604				sty.render(sty.bold, displayDate),
605				sty.render(sty.muted, fmt.Sprintf("%d %s", len(day.Commits), commitWord)))
606	
607			for _, c := range day.Commits {
608				sha := c.CommitSHA
609				if len(sha) > 7 {
610					sha = sha[:7]
611				}
612	
613				msg := "(no message)"
614				if c.CommitMsg != nil && *c.CommitMsg != "" {
615					msg = firstLine(*c.CommitMsg)
616				}
617	
618				var badges []string
619				for _, a := range uniqueCommitAgents(c) {
620					display := agentDisplayMap[a]
621					badges = append(badges, sty.renderAgent(a, display.Label))
622				}
623	
624				fileStats := fmt.Sprintf("%d files", c.FilesChanged)
625				if c.FilesChanged == 1 {
626					fileStats = "1 file"
627				}
628	
629				cpCount := len(c.Checkpoints)
630				cpStr := ""
631				if cpCount == 1 {
632					cpStr = "1 checkpoint"
633				} else if cpCount > 1 {
634					cpStr = fmt.Sprintf("%d checkpoints", cpCount)
635				}
636	
637				// Build right-aligned stats: +N / -N  M files  [K checkpoints]
638				var statParts []string
639				statParts = append(statParts,
640					sty.render(sty.add, fmt.Sprintf("+%d", c.Additions))+
641						sty.render(sty.muted, " / ")+
642						sty.render(sty.del, fmt.Sprintf("-%d", c.Deletions)))
643				statParts = append(statParts, sty.render(sty.muted, fileStats))
644				if cpStr != "" {
645					statParts = append(statParts, sty.render(sty.muted, cpStr))
646				}
647				rightSide := strings.Join(statParts, sty.render(sty.dim, "  "))
648				// Plain length for padding (ANSI codes don't count)
649				rightPlain := fmt.Sprintf("+%d / -%d  %s", c.Additions, c.Deletions, fileStats)
650				if cpStr != "" {
651					rightPlain += "  " + cpStr
652				}
653	
654				// Build left side: hash  message  repo  [badges]
655				left := sty.render(sty.commitH, sha) + " " +
656					sty.render(sty.commitM, msg) + " " +
657					sty.render(sty.muted, c.RepoFullName)
658				leftPlain := sha + " " + msg + " " + c.RepoFullName
659				var leftSb359 strings.Builder
660				for _, badge := range badges {
661					leftSb359.WriteString("  " + badge)
662				}
663				left += leftSb359.String()
664				var leftPlainSb362 strings.Builder
665				for _, a := range uniqueCommitAgents(c) {
666					leftPlainSb362.WriteString("  " + agentDisplayMap[a].Label)
667				}
668				leftPlain += leftPlainSb362.String()
669	
670				// Truncate message if line would exceed width
671				maxMsg := sty.width - (lipgloss.Width(leftPlain) - lipgloss.Width(msg)) - lipgloss.Width(rightPlain) - 2
672				if maxMsg < 10 {
673					maxMsg = 10
674				}
675				if lipgloss.Width(msg) > maxMsg {
676					msg = truncateDisplayWidth(msg, maxMsg, "...")
677					// Rebuild left side with truncated message
678					left = sty.render(sty.commitH, sha) + " " +
679						sty.render(sty.commitM, msg) + " " +
680						sty.render(sty.muted, c.RepoFullName)
681					leftPlain = sha + " " + msg + " " + c.RepoFullName
682					var leftSb378 strings.Builder
683					for _, badge := range badges {
684						leftSb378.WriteString("  " + badge)
685					}
686					left += leftSb378.String()
687					var leftPlainSb381 strings.Builder
688					for _, a := range uniqueCommitAgents(c) {
689						leftPlainSb381.WriteString("  " + agentDisplayMap[a].Label)
690					}
691					leftPlain += leftPlainSb381.String()
692				}
693	
694				gap := sty.width - lipgloss.Width(leftPlain) - lipgloss.Width(rightPlain)
695				if gap < 2 {
696					gap = 2
697				}
698				fmt.Fprintf(w, "%s%s%s\n", left, strings.Repeat(" ", gap), rightSide)
699			}
700			fmt.Fprintln(w)
701		}
702	}
