704	func uniqueCommitAgents(c userCommit) []string {
705		seen := make(map[string]struct{})
706		var result []string
707		for _, cp := range c.Checkpoints {
708			agents := cp.Agents
709			// Fall back to singular Agent field when Agents slice is empty
710			if len(agents) == 0 && cp.Agent != "" {
711				agents = []string{cp.Agent}
712			}
713			for _, a := range agents {
714				id := normalizeAgentString(a)
715				if _, ok := seen[id]; !ok {
716					seen[id] = struct{}{}
717					result = append(result, id)
718				}
719			}
720		}
721		sort.Strings(result)
722		return result
723	}
