314	func containsStr(s, sub string) bool {
315		return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
316			(len(s) > 0 && stringContains(s, sub)))
317	}
318	
319	func stringContains(s, sub string) bool {
320		for i := 0; i <= len(s)-len(sub); i++ {
321			if s[i:i+len(sub)] == sub {
322				return true
323			}
324		}
325		return false
326	}
